const winner = (n) => {
  const circle = Array.from({ length: n }, (_, i) => i + 1);
  let index = 0;
  while (circle.length > 1) {
    index = (index + 1) % circle.length;
    circle.splice(index, 1);
    if (index === circle.length) index = 0;
  }
  return circle[0];
};
let total = 0;
for (let n = 1; n <= 200; n++) total += winner(n);
return total;
